function importProgress(){operationAbort?.abort();operationAbort=new AbortController();lastJobID=null;progressStarted=performance.now();$('#importProgress')?.remove();const panel=document.createElement('div');panel.id='importProgress';panel.className='import-progress';panel.setAttribute('role','status');panel.innerHTML=`<strong>${translate('素材を読み込み中')}</strong><span id="progressPercent">0%</span><div class="progress-track"><div id="progressBar"></div></div><span id="progressLabel">${translate('準備中…')}</span><button id="cancelJob">${translate('キャンセル')}</button>`;document.body.append(panel);$('#cancelJob').onclick=()=>{cancelled=true;operationAbort?.abort();uploadRequest?.abort();if(jobID)api('/api/cancel',{job:jobID}).catch(()=>{})}}
function progressModal(title,rendering=false,source=P){operationAbort?.abort();operationAbort=new AbortController();lastJobID=null;progressStarted=performance.now();const steps=rendering?`<div class="render-summary"><span>${esc(source.aspect||'Original')}</span><span>${esc(source.export?.resolution||'1080p')}</span><span>${esc(source.export?.fps||'30')} FPS</span><span>${format(total(source))}</span></div><ol id="renderSteps" class="render-steps"><li>準備</li><li>映像・カラー・FX</li><li>テロップ合成</li><li>音声・MP4確定</li><li>完成データ検証</li></ol>`:'';modal(`<div class="modal-top"><h2>${esc(title)}</h2></div>${steps}<div class="render-progress-head"><strong id="progressPercent">0%</strong><span id="progressTime">開始しています…</span></div><div class="progress-track"><div id="progressBar"></div></div><div id="progressLabel" class="progress-caption">準備中…</div><div class="modal-actions"><button id="cancelJob">キャンセル</button></div>`);$('#cancelJob').onclick=()=>{cancelled=true;operationAbort?.abort();uploadRequest?.abort();if(jobID)api('/api/cancel',{job:jobID}).catch(()=>{});};}
function progress(operation,value){value=clamp(value,0,1);if($('#progressBar'))$('#progressBar').style.width=value*100+'%';if($('#progressLabel'))$('#progressLabel').textContent=translate(operation);if($('#progressPercent'))$('#progressPercent').textContent=Math.round(value*100)+'%';const elapsed=(performance.now()-progressStarted)/1000,eta=value>.025&&value<1?elapsed*(1-value)/value:0;if($('#progressTime'))$('#progressTime').textContent=currentLanguage()==='en'?`Elapsed ${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')}${eta?` · About ${Math.ceil(eta)}s remaining`:''}`:`経過 ${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')}${eta?` · 残り目安 ${Math.ceil(eta)}秒`:''}`;const steps=$$('#renderSteps li'),index=value>=.96?4:value>=.9?3:value>=.78?2:value>=.05?1:0;steps.forEach((step,i)=>{step.classList.toggle('active',i===index);step.classList.toggle('done',i<index)});status(operation)}
async function watchJob(id){jobID=id;lastJobID=id;while(true){if(cancelled)await api('/api/cancel',{job:id}).catch(()=>{});let j=await api('/api/job/'+id);progress(j.operation,j.progress);if(j.status==='done'){jobID=null;return j.result}if(j.status==='error'||j.status==='cancelled'){jobID=null;throw Error(j.error||'処理を中止しました。')}await new Promise(r=>setTimeout(r,500))}}
