async function scan(){if(mediaKind(mediaOf(current()))==='image')return toast('動きの解析は動画素材を選んでください。');if(busy||!canEdit())return;pause();busy=true;cancelled=false;let c=current(),m=mediaOf(c);progressModal('素材を解析');try{let result;if(engine){let r=await api('/api/analyze',{media:m.id,intent:P.intent});result=await watchJob(r.job)}else{let url=linkURL(m);if(!url)throw Error('元動画を再リンクしてください。');const v=document.createElement('video');v.preload='auto';v.playsInline=true;v.muted=true;const cv=document.createElement('canvas');cv.width=cv.height=64;const ctx=cv.getContext('2d',{willReadFrequently:true});scanWorker=new Worker('analysis-worker.js');const ask=(d,transfer=[])=>new Promise((r,j)=>{scanWorker.onmessage=e=>r(e.data);scanWorker.onerror=e=>j(Error(e.message));scanWorker.postMessage(d,transfer)});try{const ready=waitForMedia(v,'loadeddata',{signal:operationAbort?.signal});v.src=url;v.load();await ready;await ask({type:'reset'});let sampleFps=Math.min(4,1800/m.duration),n=Math.max(1,Math.ceil(m.duration*sampleFps));for(let i=0;i<n;i++){if(cancelled)throw Error('解析をキャンセルしました。');let t=Math.min(m.duration-.001,(i+.1)/sampleFps);if(Math.abs(v.currentTime-t)>.0001){await seekMedia(v,t,{signal:operationAbort?.signal})}ctx.drawImage(v,0,0,64,64);let image=ctx.getImageData(0,0,64,64);await ask({type:'frame',time:t,buffer:image.data.buffer},[image.data.buffer]);progress('動き・静止・鮮鋭度を解析中',i/n)}result=await ask({type:'finish',media:m.id,intent:P.intent,duration:m.duration,sampleFps})}finally{scanWorker?.terminate();scanWorker=null;v.removeAttribute('src');v.load()}}delete result.samples;mutate(()=>{P.analysis=P.analysis.filter(a=>a.media!==m.id||a.intent!==P.intent);P.analysis.push(result)});$('#modal').close();status('解析が完了しました。');toast(result.markers.length+'個の候補を表示しました。素材は変更していません。')}catch(e){errorModal(e)}finally{busy=false;jobID=null}}
