async function deviceCheck(){if(busy)return;busy=true;cancelled=false;pause();progressModal('端末の書き出しテスト');try{const r=await fetch('device-test.mp4');if(!r.ok)throw Error('テスト素材を読み込めません。');const file=new File([await r.blob()],'device-test.mp4',{type:'video/mp4'});const m={id:'device-check',name:file.name,width:160,height:90,duration:1,fps:30,audio:true,hdr:false};const p=project();p.name='Device check';p.media=[m];p.clips=[{...clip(m),speed:.5,endSpeed:2,curve:'ease-in-out'}];p.aspect='9:16';p.clips[0].color={...lookPresets.COLD};const freeze=frozenClip(p,p.clips[0].id,.2,.3);freeze.fadeIn=.1;freeze.fadeOut=.1;p.effects=[{id:uid(),type:'flash',start:0,duration:.16,strength:1},{id:uid(),type:'black-out',start:Math.max(0,total(p)-.2),duration:.2,strength:1}];const extracted=detachAudio(p,p.clips[0].id,0);if(extracted){for(let k=1;k<4;k++)p.audioClips.push({...structuredClone(extracted),id:uid(),layer:k,audio:{...extracted.audio,volume:.15}})}p.clips.push({...structuredClone(freeze),id:uid(),layer:1,opacity:.4});p.texts=[{id:uid(),text:'MOTION',start:0,end:total(p),font:'Sans',align:'center',size:72,x:.5,y:.8,opacity:1,motion:'rise',motionDuration:.2,fadeIn:.15,fadeOut:.15}];const result=await renderOnDevice(p,[{id:m.id,file}],{preview:true,signal:operationAbort.signal,onProgress:progress});result.test=true;showDeviceResult(result,p.name,{modal,head,esc,status});await deleteRender(result.path);status('端末テスト成功：映像・音声の生成と全尺検証が完了しました。テスト用ファイルは自動で整理しました。')}catch(e){errorModal(e,deviceCheck)}finally{busy=false;jobID=null}}


function motionAnimationControls(c){return `<div class="control-section"><div class="eyebrow">FRAME MOTION</div>${selectControl('motionPreset','動き',c.motionPreset||'none',[['none','動きなし'],['push-in','ゆっくり寄る'],['pull-out','ゆっくり引く'],['pan-left','左へパン'],['pan-right','右へパン'],['pan-up','上へパン'],['pan-down','下へパン']])}${(c.motionPreset||'none')!=='none'?slider('motionAmount','動きの量',c.motionAmount??.12,.01,.5,.01):''}<p class="small-note">動画と静止画の両方に動きを加えられます。プレビューと書き出しへ同じ設定を反映します。</p></div>`}
function motionTools(c){return `<div class="control-section"><div class="eyebrow">FREEZE FRAME</div><button id="freezeHere" class="wide">❚❚ このフレームをV3で静止</button>${c.freezeDuration?slider('freezeDuration','静止する長さ',c.freezeDuration,1/30,60,1/30,' sec'):''}</div>`}
function fxInspector(){const e=P.effects?.find(e=>e.id===selectedEffect);return `<div class="control-section"><div class="eyebrow">EFFECT LIBRARY</div>${Object.entries(effectNames).map(([k,v])=>`<button data-addfx="${k}" draggable="true" class="wide fx-source" title="タイムラインへドラッグして配置">⠿ ${v}</button>`).join('')}<p class="small-note">クリックで再生ヘッドへ追加、またはFXトラックの任意位置へドラッグします。</p></div><div class="control-section"><div class="eyebrow">TIMELINE EFFECTS</div>${(P.effects||[]).map(effect=>`<button data-fx="${effect.id}" class="wide ${effect.id===selectedEffect?'selected':''}">${effectNames[effect.type]} · F/T${(effect.layer||0)+1} · ${effect.start.toFixed(2)}s</button>`).join('')||'<p class="small-note">FXはまだ配置されていません。</p>'}${e?`${slider('effect.start','開始',e.start,0,Math.max(.01,duration()),.01,' sec')}${slider('effect.duration','全体の長さ',e.duration,1/30,Math.max(1,duration()),1/30,' sec')}${e.type!=='flash'?slider('effect.hold',e.type==='black-in'?'最初の黒画面を保持':'最後の黒画面を保持',e.hold||0,0,Math.max(0,e.duration-1/60),1/30,' sec'):''}${slider('effect.strength','強さ',e.strength,0,1,.01)}<p class="small-note">保持以外の時間がフェード区間になります。プレビューと書き出しは同じ時刻計算を使います。</p><button id="deleteEffect" class="wide">この効果を削除</button>`:''}</div>`}
