function drawLookThumbnails(){
 if(tab!=='look'||playing||previewRow()?.clip.id!==selected)return;
 const c=current(),m=mediaOf(c),source=m?.kind==='image'?stillPreview.bitmap:video;if(!source||source.readyState!==undefined&&source.readyState<2)return;
 try{
 if(!lookThumbCanvas){lookThumbCanvas=document.createElement('canvas');lookThumbPainter=renderer(lookThumbCanvas,{width:144,height:90,preserve:true})}
 if(!lookThumbPainter)return;
 Object.values(getPresets()).forEach((color,i)=>{const img=document.querySelector('[data-lookthumb="'+i+'"]');if(!img)return;lookThumbPainter.draw(source,{...c,color,lookAmount:1},'16:10');img.src=lookThumbCanvas.toDataURL('image/jpeg',.72);img.hidden=false});
 }catch{}
}

